import { aborter } from "./aborter";

const BASE_URL =
  process.env.REACT_APP_CASTIA_WORKER_URL ||
  "https://castia-worker.lektodesigns.workers.dev";

const DEFAULT_TIMEOUT_MS = 10000;

// P3-4: Worker endpoints have internal TTLs, so we don't need a browser cache
// but we should avoid redundant inflight requests.
const inflight = new Map();

async function workerFetch(endpoint, { signal, force = false } = {}) {
  const url = `${BASE_URL}${endpoint}`;

  const existing = inflight.get(url);
  if (!force && existing && !existing.signal.aborted) return existing.promise;

  const combined = aborter(DEFAULT_TIMEOUT_MS, signal);
  const request = { signal: combined.signal, promise: null };
  const promise = (async () => {
    try {
      const res = await fetch(url, {
        headers: { Accept: "application/json" },
        signal: combined.signal,
      });
      if (!res.ok) {
        let body;
        try { body = await res.json(); } catch { body = null; }
        const message = body?.error || body?.message || `HTTP ${res.status}`;
        const err = new Error(message);
        err.status = res.status;
        err.retryable = res.status === 429 || res.status >= 500;
        err.endpoint = endpoint;
        err.body = body;
        throw err;
      }
      return res.json();
    } finally {
      combined.cleanup();
      // A forced refresh may have replaced this entry while the old request
      // was winding down. Never delete that newer request's coalescing slot.
      if (inflight.get(url) === request) inflight.delete(url);
    }
  })();

  request.promise = promise;
  inflight.set(url, request);
  return promise;
}

export function fetchPrices({ signal } = {}) {
  return workerFetch("/prices", { signal });
}

export function fetchSellers({ signal } = {}) {
  return workerFetch("/sellers", { signal });
}

export function fetchAuctions(itemQuery, { signal } = {}) {
  const query = typeof itemQuery === "string" ? { item: itemQuery } : (itemQuery || {});
  const params = new URLSearchParams();
  if (query.item) params.set("item", query.item);
  if (query.set) params.set("set", query.set);
  if (query.tier) params.set("tier", String(query.tier));
  if (query.variant) params.set("variant", query.variant);
  return workerFetch(`/auctions?${params.toString()}`, { signal });
}

export function fetchSellerAuctions(sellerName, { limit = 100, cursor = null, signal } = {}) {
  const params = new URLSearchParams({
    seller: sellerName,
    limit: String(limit),
  });
  if (cursor) params.set("cursor", cursor);
  return workerFetch(`/seller-auctions?${params.toString()}`, { signal });
}

export function fetchChestShops({ item, exact, seller, limit, tier, set, variant, sort, cursor, signal, force } = {}) {
  const params = new URLSearchParams();
  if (item) params.set("item", item);
  if (exact) params.set("exact", "true");
  if (seller) params.set("seller", seller);
  if (limit) params.set("limit", String(limit));
  if (tier) params.set("tier", tier);
  if (set) params.set("set", set);
  if (variant) params.set("variant", variant);
  if (sort) params.set("sort", sort);
  if (cursor) params.set("cursor", cursor);
  const qs = params.toString();
  return workerFetch(`/chest-shops${qs ? `?${qs}` : ""}`, { signal, force });
}

/**
 * Compatibility fallback for an older Worker that only accepts exact item
 * names. This is intentionally used only after a filtered request returns no
 * rows, then scans the bounded active catalog client-side for fuzzy matches.
 */
export async function fetchAllChestShops({ item, exact, seller, sort, signal } = {}) {
  const shops = [];
  let cursor = null;
  for (let page = 0; page < 10; page += 1) {
    const response = await fetchChestShops({ item, exact, seller, limit: 1000, sort, cursor, signal });
    const rows = Array.isArray(response) ? response : response?.shops || response?.rows || [];
    shops.push(...rows);
    cursor = response?.nextCursor || null;
    if (!cursor) break;
  }
  if (cursor) throw new Error("The shop catalogue is too large to load completely. Refine your search.");
  return { source: "chest_shop", shops, nextCursor: null };
}

export function fetchStock({ item, seller, server, limit, freshWithinHours, signal } = {}) {
  const params = new URLSearchParams();
  if (item) params.set("item", item);
  if (seller) params.set("seller", seller);
  if (server) params.set("server", server);
  if (limit) params.set("limit", String(limit));
  if (freshWithinHours) params.set("freshWithinHours", String(freshWithinHours));
  const qs = params.toString();
  return workerFetch(`/stock${qs ? `?${qs}` : ""}`, { signal });
}

export function fetchWarpZones({ server, dimension, owner, limit, signal, force } = {}) {
  const params = new URLSearchParams();
  if (server) params.set("server", server);
  if (dimension) params.set("dimension", dimension);
  if (owner) params.set("owner", owner);
  if (limit) params.set("limit", String(limit));
  const qs = params.toString();
  return workerFetch(`/warp-zones${qs ? `?${qs}` : ""}`, { signal, force });
}
